ALTER TABLE public.organizations ADD COLUMN description text, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.organization_settings ADD COLUMN phone text, ADD COLUMN address text, ADD COLUMN postal_code text, ADD COLUMN city text, ADD COLUMN responsible_name text, ADD COLUMN cover_path text, ADD COLUMN social_links jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.organization_players ADD COLUMN category text, ADD COLUMN membership_status text, ADD COLUMN notes text;
CREATE OR REPLACE FUNCTION public.enforce_organization_onboarding_gate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id OR NEW.slug IS DISTINCT FROM OLD.slug) THEN RAISE EXCEPTION 'Organization identity is immutable'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.enforce_legacy_organization_gate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE central_id uuid; BEGIN SELECT id INTO central_id FROM public.organizations WHERE slug='foxes-darts'; IF TG_OP='INSERT' AND NEW.organization_id IS NULL THEN NEW.organization_id:=central_id; END IF; IF NEW.organization_id IS NULL THEN RAISE EXCEPTION 'Organization required'; END IF; IF TG_OP='UPDATE' AND NEW.organization_id IS DISTINCT FROM OLD.organization_id THEN RAISE EXCEPTION 'Organization reassignment is forbidden'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.create_organization_space(_name text,_slug text,_description text,_settings jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE new_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); IF (SELECT count(*) FROM public.organizations WHERE created_by=auth.uid() AND created_at>now()-interval '1 day')>=3 THEN RAISE EXCEPTION 'Daily organization creation limit reached'; END IF; IF length(trim(_name))<2 OR _slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' THEN RAISE EXCEPTION 'Invalid organization'; END IF; INSERT INTO public.organizations(name,slug,description,status,created_by) VALUES(left(trim(_name),120),_slug,left(_description,4000),'active',auth.uid()) RETURNING id INTO new_id; INSERT INTO public.organization_members(organization_id,user_id,role) VALUES(new_id,auth.uid(),'ORGANIZATION_OWNER'); INSERT INTO public.organization_players(organization_id,user_id) VALUES(new_id,auth.uid()); INSERT INTO public.organization_settings(organization_id,contact_email,organization_type,phone,address,postal_code,city,responsible_name,primary_color,secondary_color) VALUES(new_id,_settings->>'email',_settings->>'type',_settings->>'phone',_settings->>'address',_settings->>'postal_code',_settings->>'city',_settings->>'responsible_name',_settings->>'primary_color',_settings->>'secondary_color'); INSERT INTO public.organization_audit_events(organization_id,actor_id,action) VALUES(new_id,auth.uid(),'organization.created'); RETURN new_id; END $$;
REVOKE ALL ON FUNCTION public.create_organization_space(text,text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_organization_space(text,text,text,jsonb) TO authenticated;
CREATE FUNCTION public.create_organization_invitation(_organization_id uuid,_email text,_role text,_token_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invitation_id uuid; BEGIN IF NOT public.can_manage_organization(_organization_id) THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM 1 FROM public.organizations WHERE id=_organization_id FOR UPDATE; IF _role NOT IN ('ORGANIZATION_ADMIN','TOURNAMENT_MANAGER') OR _email !~ '^[^@ ]+@[^@ ]+\.[^@ ]+$' OR length(_token_hash)<>64 THEN RAISE EXCEPTION 'Invalid invitation'; END IF; IF (SELECT count(*) FROM public.organization_invitations WHERE organization_id=_organization_id AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'Invitation rate limit reached'; END IF; UPDATE public.organization_invitations SET status='cancelled' WHERE organization_id=_organization_id AND lower(email)=lower(trim(_email)) AND status='pending'; INSERT INTO public.organization_invitations(organization_id,email,role,token_hash,expires_at,invited_by) VALUES(_organization_id,lower(trim(_email)),_role,_token_hash,now()+interval '7 days',auth.uid()) RETURNING id INTO invitation_id; INSERT INTO public.organization_audit_events(organization_id,actor_id,action,details) VALUES(_organization_id,auth.uid(),'invitation.created',jsonb_build_object('invitation_id',invitation_id)); RETURN invitation_id; END $$;
REVOKE ALL ON FUNCTION public.create_organization_invitation(uuid,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_organization_invitation(uuid,text,text,text) TO authenticated;
CREATE FUNCTION public.respond_organization_invitation(_token_hash text,_accept boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invitation public.organization_invitations; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; SELECT * INTO invitation FROM public.organization_invitations WHERE token_hash=_token_hash FOR UPDATE; IF invitation.id IS NULL OR invitation.status<>'pending' OR invitation.expires_at<=now() OR lower(invitation.email)<>lower(coalesce(auth.jwt()->>'email','')) THEN RAISE EXCEPTION 'Invitation unavailable for this account'; END IF; IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=invitation.organization_id AND status='active') THEN RAISE EXCEPTION 'Organization inactive'; END IF; UPDATE public.organization_invitations SET status=CASE WHEN _accept THEN 'accepted' ELSE 'declined' END,accepted_by=auth.uid() WHERE id=invitation.id; IF _accept THEN INSERT INTO public.organization_members(organization_id,user_id,role) VALUES(invitation.organization_id,auth.uid(),invitation.role) ON CONFLICT DO NOTHING; INSERT INTO public.organization_players(organization_id,user_id) VALUES(invitation.organization_id,auth.uid()) ON CONFLICT DO NOTHING; END IF; INSERT INTO public.notifications(recipient_id,organization_id,kind,payload) VALUES(invitation.invited_by,invitation.organization_id,'invitation.response',jsonb_build_object('accepted',_accept)); INSERT INTO public.organization_audit_events(organization_id,actor_id,action) VALUES(invitation.organization_id,auth.uid(),CASE WHEN _accept THEN 'invitation.accepted' ELSE 'invitation.declined' END); RETURN invitation.organization_id; END $$;
REVOKE ALL ON FUNCTION public.respond_organization_invitation(text,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_organization_invitation(text,boolean) TO authenticated;
CREATE FUNCTION public.change_organization_collaborator(_organization_id uuid,_user_id uuid,_role text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_role text; BEGIN IF NOT public.can_manage_organization(_organization_id) THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM 1 FROM public.organizations WHERE id=_organization_id FOR UPDATE; SELECT role INTO old_role FROM public.organization_members WHERE organization_id=_organization_id AND user_id=_user_id; IF old_role IS NULL OR old_role='ORGANIZATION_OWNER' OR _user_id=auth.uid() THEN RAISE EXCEPTION 'Protected collaborator'; END IF; IF _role IS NOT NULL AND _role NOT IN ('ORGANIZATION_ADMIN','TOURNAMENT_MANAGER') THEN RAISE EXCEPTION 'Invalid role'; END IF; DELETE FROM public.tournament_manager_assignments WHERE user_id=_user_id AND tournament_id IN(SELECT id FROM public.tournaments WHERE organization_id=_organization_id); IF _role IS NULL THEN DELETE FROM public.organization_members WHERE organization_id=_organization_id AND user_id=_user_id; ELSE UPDATE public.organization_members SET role=_role WHERE organization_id=_organization_id AND user_id=_user_id; END IF; INSERT INTO public.organization_audit_events(organization_id,actor_id,action,details) VALUES(_organization_id,auth.uid(),'collaborator.changed',jsonb_build_object('user_id',_user_id,'role',_role)); END $$;
REVOKE ALL ON FUNCTION public.change_organization_collaborator(uuid,uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.change_organization_collaborator(uuid,uuid,text) TO authenticated;
CREATE FUNCTION public.transfer_organization_ownership(_organization_id uuid,_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.organizations WHERE id=_organization_id AND status='active' FOR UPDATE; IF NOT public.is_platform_admin() AND NOT EXISTS(SELECT 1 FROM public.organization_members WHERE organization_id=_organization_id AND user_id=auth.uid() AND role='ORGANIZATION_OWNER') THEN RAISE EXCEPTION 'Owner permission required'; END IF; IF _user_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.organization_members WHERE organization_id=_organization_id AND user_id=_user_id) THEN RAISE EXCEPTION 'Existing collaborator required'; END IF; UPDATE public.organization_members SET role='ORGANIZATION_ADMIN' WHERE organization_id=_organization_id AND role='ORGANIZATION_OWNER'; UPDATE public.organization_members SET role='ORGANIZATION_OWNER' WHERE organization_id=_organization_id AND user_id=_user_id; INSERT INTO public.organization_audit_events(organization_id,actor_id,action,details) VALUES(_organization_id,auth.uid(),'ownership.transferred',jsonb_build_object('new_owner',_user_id)); END $$;
REVOKE ALL ON FUNCTION public.transfer_organization_ownership(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.transfer_organization_ownership(uuid,uuid) TO authenticated;
GRANT UPDATE(name,description,updated_at) ON public.organizations TO authenticated;
CREATE POLICY organizations_management_update ON public.organizations FOR UPDATE TO authenticated USING(public.can_manage_organization(id)) WITH CHECK(public.can_manage_organization(id));
GRANT UPDATE ON public.organization_settings TO authenticated;
CREATE POLICY organization_settings_management_update ON public.organization_settings FOR UPDATE TO authenticated USING(public.can_manage_organization(organization_id)) WITH CHECK(public.can_manage_organization(organization_id));
GRANT SELECT(id,organization_id,email,role,expires_at,status,created_at,invited_by) ON public.organization_invitations TO authenticated;
CREATE POLICY invitations_management_read ON public.organization_invitations FOR SELECT TO authenticated USING(public.can_manage_organization(organization_id));
GRANT UPDATE(status) ON public.organization_invitations TO authenticated;
CREATE POLICY invitations_management_cancel ON public.organization_invitations FOR UPDATE TO authenticated USING(public.can_manage_organization(organization_id)) WITH CHECK(public.can_manage_organization(organization_id) AND status='cancelled');
GRANT UPDATE(category,membership_status,notes) ON public.organization_players TO authenticated;
CREATE POLICY organization_players_management_update ON public.organization_players FOR UPDATE TO authenticated USING(public.can_manage_organization(organization_id)) WITH CHECK(public.can_manage_organization(organization_id));
GRANT UPDATE(read_at) ON public.notifications TO authenticated;
CREATE POLICY notifications_mark_read ON public.notifications FOR UPDATE TO authenticated USING(recipient_id=auth.uid()) WITH CHECK(recipient_id=auth.uid());
CREATE POLICY audit_organization_read ON public.organization_audit_events FOR SELECT TO authenticated USING(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can insert tournaments" ON public.tournaments WITH CHECK(public.can_manage_organization(organization_id) OR (created_by=auth.uid() AND EXISTS(SELECT 1 FROM public.organization_members m JOIN public.organizations o ON o.id=m.organization_id WHERE m.organization_id=tournaments.organization_id AND m.user_id=auth.uid() AND m.role='TOURNAMENT_MANAGER' AND o.status='active')));
CREATE FUNCTION public.assign_tournament_creator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.created_by IS NOT NULL AND EXISTS(SELECT 1 FROM public.organization_members WHERE organization_id=NEW.organization_id AND user_id=NEW.created_by AND role='TOURNAMENT_MANAGER') THEN INSERT INTO public.tournament_manager_assignments(tournament_id,user_id,assigned_by) VALUES(NEW.id,NEW.created_by,NEW.created_by) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.assign_tournament_creator() FROM PUBLIC;
CREATE TRIGGER tournaments_assign_creator AFTER INSERT ON public.tournaments FOR EACH ROW EXECUTE FUNCTION public.assign_tournament_creator();